package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.FieldPosition;
import java.text.Format;
import java.text.NumberFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.util.*;
import java.util.Locale;
import org.apache.commons.math3.complex.Complex;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ComplexFormat_parse_TriageGen0Test {

    private ComplexFormat formatter;

    @Before
    public void setUp() {
        // Default constructor uses "i" as imaginary character and default NumberFormat
        formatter = new ComplexFormat();
    }

    @Test
    public void testParse_ValidRealOnly() {
        String source = "123.45";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(123.45, 0.0), result);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_ValidComplexPositive() {
        String source = "123.45+67.89i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(123.45, 67.89), result);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_ValidComplexNegative() {
        String source = "123.45-67.89i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(123.45, -67.89), result);
        assertEquals(source.length(), pos.getIndex());
    }

    @Test
    public void testParse_WithWhitespace() {
        String source = "  123.45  +  67.89i  ";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(123.45, 67.89), result);
        // Note: Depending on how parseAndIgnoreWhitespace is implemented, 
        // it might leave trailing whitespace or consume it. 
        // Based on logic, it consumes whitespace before real and between sign/imaginary.
    }

    @Test
    public void testParse_InvalidReal() {
        String source = "abc+1i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
    }

    @Test
    public void testParse_InvalidSign() {
        String source = "123.45?67.89i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // startIndex for sign was at the '?'
        assertEquals(5, pos.getErrorIndex());
    }

    @Test
    public void testParse_InvalidImaginaryNumber() {
        String source = "123.45+abc i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
    }

    @Test
    public void testParse_InvalidImaginaryCharacter() {
        String source = "123.45+67.89j"; // expected 'i'
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertNull(result);
        assertEquals(0, pos.getIndex());
        // error index should be where 'j' was expected
        // "123.45+67.89" is length 12
        assertEquals(12, pos.getErrorIndex());
    }

    @Test
    public void testParse_CustomImaginaryCharacter() {
        formatter = new ComplexFormat("j");
        String source = "1.0+2.0j";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(1.0, 2.0), result);
        assertEquals(7, pos.getIndex());
    }

    @Test
    public void testParse_PartialString() {
        String source = "123.45+67.89i extra";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(123.45, 67.89), result);
        assertEquals(12, pos.getIndex()); // index after 'i'
    }

    @Test
    public void testParse_ZeroRealImaginary() {
        String source = "0+0i";
        ParsePosition pos = new ParsePosition(0);
        Complex result = formatter.parse(source, pos);

        assertEquals(new Complex(0.0, 0.0), result);
        assertEquals(4, pos.getIndex());
    }
}
